mapper.select:
SELECT 
  FROM tb_net_node n
 WHERE n.node_id = #{nodeId}

SELECT COUNT(*)
  FROM tb_server s
 WHERE s.ip_addr = #{ipAddr}

   AND s.server_id <> #{excludeServerId}

mapper.insert:
INSERT INTO tb_server_metric (
       server_id, cpu_pct, mem_pct, disk_pct, session_cnt, collect_dt
) VALUES (
       #{serverId}, #{cpuPct}, #{memPct}, #{diskPct, jdbcType=DECIMAL}, #{sessionCnt}, CURRENT_TIMESTAMP
)

mapper.select:
SELECT 
  FROM tb_server_process p
 WHERE p.server_id = #{serverId}
   AND p.proc_id   = #{procId}

SELECT COALESCE(MAX(p.sort_ord), 0)
  FROM tb_server_process p
 WHERE p.server_id = #{serverId}

mapper.insert:
INSERT INTO tb_server_process (
       server_id, proc_nm, exec_path, pid, cpu_pct, mem_pct, running_yn, sort_ord, reg_dt, upd_dt
) VALUES (
       #{serverId}, #{procNm}, #{execPath}, #{pid, jdbcType=INTEGER}, #{cpuPct}, #{memPct}, #{runningYn}, #{sortOrd},
       CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)

mapper.delete:
DELETE FROM tb_server_process
 WHERE server_id = #{serverId}
   AND proc_id   = #{procId}

DELETE FROM tb_server_metric_hist
 WHERE server_id = #{serverId}
   AND collect_dt < #{before}

DELETE FROM tb_process_metric_hist
 WHERE server_id = #{serverId}
   AND collect_dt < #{before}
